/* ─────────── v249.js ─────────── */
/* ═══════════════════════════════════════════════════════════════════════════
   v249 · “STEADY” — the instruments for a blink, and the last guard against one.

   The owner, verbatim: “Screen blinks and still slow loading.”

   The blink is answered in three places, all of them removals:

     · css/v249.css — nothing that is content may start at `opacity: 0` and fade
       in. Entrance motion travels; it does not fade up from nothing. The route
       rise, the `.rv` reveals, the review rows and the picture fade all lost
       their invisible first keyframe.
     · index.html + `html.shv-warm` — the maroon curtain is not painted at all
       for a device that already holds the catalogue, so a reload goes straight
       to the page instead of flashing a splash over it.
     · js/app.js + js/v166.js — a late boot batch and a background catalogue
       repair no longer rewrite #view. They adopt the data and patch the
       `.js-price` slots in place. A second full render was the biggest blink
       and the biggest duplicate download in the product.

   This file is what is left: it counts the blinks that still happen, so the next
   report can say “the view was replaced twice without a tap” instead of “it
   blinks”, and it stops the one case the CSS cannot: a repaint that arrives
   under the shopper's thumb. If #view is replaced while a gesture is in flight,
   the replacement is deferred to the next calm frame — the same rule v242 wrote
   for the boot batch, applied to every renderer.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window.__shvSteady) return;
  window.__shvSteady = true;

  var doc = document, root = doc.documentElement;
  var view = doc.getElementById('view');
  var now = function () { return (window.performance && performance.now) ? performance.now() : Date.now(); };

  /* ── 1 · what the page already knows about itself ─────────────────────── */
  var warm = root.classList.contains('shv-warm');
  var curtainPainted = !warm && !!doc.getElementById('preloader');

  /* ── 2 · count view replacements that no tap asked for ────────────────────
     A replacement within 1.2 s of a tap is a navigation. A replacement with no
     tap behind it is a repaint — and a repaint is what a shopper sees as the
     screen blinking. Each one is recorded with the time since the page opened
     and whether a gesture was in flight. */
  var renders = [];
  var lastTap = 0;
  ['pointerdown', 'touchstart', 'wheel', 'keydown'].forEach(function (ev) {
    addEventListener(ev, function () { lastTap = now(); }, { passive: true, capture: true });
  });

  function note(why) {
    var t = Math.round(now());
    renders.push({ at: t, sinceTap: lastTap ? Math.round(t - lastTap) : null, gesture: root.classList.contains('shv-scrolling'), why: why });
    if (renders.length > 10) renders.shift();
    return t;
  }

  if (view && window.MutationObserver) {
    var t0 = now();
    var armed = false;
    new MutationObserver(function (list) {
      for (var i = 0; i < list.length; i++) {
        if (list[i].addedNodes && list[i].addedNodes.length) {
          /* the first fill of the skeleton is the page opening, not a blink */
          if (!armed) { armed = true; return; }
          note('view replaced');
          return;
        }
      }
    }).observe(view, { childList: true });
    void t0;
  }

  /* ── 3 · a render may not land under a thumb ─────────────────────────────
     Nothing in this release should be repainting the view, so this is a belt:
     any renderer that still rewrites #view while a gesture is live or a press
     was registered in the last 400 ms is deferred until the page is still. The
     router itself (`route()` on a real hashchange) is never touched — this hooks
     only the *programmatic* doors: Shivaa.redraw() and boot()'s calm repaint. */
  function calm() {
    return !root.classList.contains('shv-scrolling') && (!lastTap || now() - lastTap > 400);
  }
  function deferUntilCalm(fn) {
    var tries = 0;
    (function step() {
      if (calm() || ++tries > 40) { fn(); return; }
      setTimeout(step, 150);
    })();
  }
  try {
    var S = window.Shivaa;
    if (S && typeof S.redraw === 'function' && !S.__v249redraw) {
      var raw = S.redraw;
      S.redraw = function () {
        var args = arguments, self = this;
        if (calm()) return raw.apply(self, args);
        deferUntilCalm(function () { raw.apply(self, args); });
        return undefined;
      };
      S.__v249redraw = true;
    }
  } catch (e) {}

  /* ── 4 · the report ─────────────────────────────────────────────────────
     One line, in the same shape as Shivaa.v248.report(), so the two can sit in
     the same message and answer different halves of the question:
       v248 = how long did a tap take
       v249 = how many times did the page redraw itself, and was the curtain up */
  window.Shivaa = window.Shivaa || {};
  window.Shivaa.v249 = {
    warm: warm,
    curtainPainted: curtainPainted,
    renders: function () { return renders.slice(); },
    report: function () {
      var strange = renders.filter(function (r) { return r.sinceTap === null || r.sinceTap > 1200; });
      return 'steady ' + (window.__SHIVAA_REL || 0) +
        ' · start ' + (warm ? 'warm (no curtain)' : (curtainPainted ? 'cold (curtain)' : 'cold')) +
        ' · unasked repaints ' + strange.length + '/' + renders.length +
        (strange.length ? ' [' + strange.map(function (r) { return r.at + 'ms' + (r.gesture ? '/gesture' : ''); }).join(' ') + ']' : '') +
        ' · ' + (window.Shivaa.v248 && window.Shivaa.v248.report ? '' : '');
    }
  };
})();

/* ─────────── v250.js ─────────── */
/* ═══════════════════════════════════════════════════════════════════════════
   v250 · “STILL” — the scripted half of the phone's paint budget, and the page
   that will not move.

   Three jobs, none of them cosmetic:

     1 · NAME THE DEVICE. `html.shv-mobile` is set from `matchMedia` in
         index.html before the first frame (so nothing flashes in or out), and
         this file re-asserts it after boot in case the page was restored from
         the back/forward cache with a different viewport. css/v250.css hangs
         every compositor budget rule off that class. It is a class and not a
         `@media (pointer: coarse)` block for a practical reason: a media query
         cannot be tested here, and an untestable rule is how four releases in a
         row shipped decoration that nobody could measure.

     2 · GIVE A FROZEN PAGE BACK. `lockScroll()` counter + `html.no-scroll` is
         how every sheet locks the page behind it. One missed release and the shop
         cannot be scrolled and looks dead — “the page doesn't move anywhere
         sometimes”. This watches for that exact shape: the lock is on, nothing
         that could own it is open, and the shopper is trying to move the page.
         After 700 ms of that, the page is handed back (app.js
         forceUnlockScroll). It never fires while a sheet is open, and it never
         fires unprompted — only when a gesture says “I am trying to scroll”.

     3 · MEASURE IT. `Shivaa.v250.audit()` counts what the phone is actually
         compositing at this moment: backdrop-filter passes, blending groups,
         running animations, the infinite ones, layer promotions. The numbers in
         css/v250.css's header came from exactly this measurement; the next
         report can be a number instead of an adjective.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window.__shvStill) return;
  window.__shvStill = true;

  var doc = document, root = doc.documentElement;
  var NOFX = /[?&]nofx=1/.test(location.search);

  /* ── 1 · name the device ──────────────────────────────────────────────── */
  function isMobile() {
    try {
      if (matchMedia('(pointer: coarse)').matches) return true;
      if (matchMedia('(max-width: 820px)').matches) return true;
    } catch (e) {}
    return (window.innerWidth || 1024) <= 820;
  }
  function nameDevice() {
    var m = isMobile();
    root.classList.toggle('shv-mobile', m);
    root.setAttribute('data-shv-device', m ? 'phone' : 'desktop');
  }
  nameDevice();
  addEventListener('resize', nameDevice, { passive: true });
  addEventListener('pageshow', nameDevice, { passive: true });

  /* ── 2 · the page that will not move ──────────────────────────────────── */
  /* everything that could legitimately own the lock */
  /* v250 — “open” is not the same as “in the document”. The first version of this
     list included `.mega-panel`, which lives in index.html permanently and is
     only revealed by a class; the watchdog therefore believed a sheet was always
     open and never handed a frozen page back. Every candidate must now (a) match
     an OPEN marker and (b) be actually visible. */
  var OWNERS = [
    '#modalOverlay.open', '.modal.open', '[role="dialog"].open',
    '#searchDrawer.open', '#searchScrim.open', '#searchScrim.on',
    '#drawerScrim.open', '#drawerScrim.on', 'body.drawer-open', 'body.nav-open',
    '.mega-panel.open', '.mega-panel.on', '.mega-panel[data-open="1"]',
    '.fsheet-overlay.open', '.wa-modal.on', '.nb-modal.on',
    '[class$="-sheet"].open', '[class$="-sheet"].on', '.sheet.open',
    '#miniCart.open', '.cart-drawer.open'
  ].join(', ');

  function visible(el) {
    try {
      var s = getComputedStyle(el);
      if (!s) return false;
      if (s.display === 'none' || s.visibility === 'hidden') return false;
      if (s.opacity === '0') return false;
      var r = el.getBoundingClientRect();
      if (r && (r.width === 0 || r.height === 0) && s.position !== 'fixed') return false;
      return true;
    } catch (e) { return true; }
  }

  function overlaysOpen() {
    var hits;
    try { hits = doc.querySelectorAll(OWNERS); } catch (e) { return true; }
    for (var i = 0; i < hits.length; i++) if (visible(hits[i])) return true;
    return false;
  }

  var frozenNoted = [];
  function checkFrozen() {
    if (!root.classList.contains('no-scroll')) return false;
    if (overlaysOpen()) return false;
    if (window.Shivaa && typeof window.Shivaa.forceUnlockScroll === 'function') {
      window.Shivaa.forceUnlockScroll();
    } else {
      root.classList.remove('no-scroll');
      root.style.overflow = '';
    }
    frozenNoted.push(Math.round((window.performance && performance.now) ? performance.now() : Date.now()));
    if (frozenNoted.length > 10) frozenNoted.shift();
    return true;
  }

  /* only while the shopper is trying to move the page — never on a timer alone */
  var pending = 0;
  function watch() {
    clearTimeout(pending);
    pending = setTimeout(checkFrozen, 700);
  }
  ['pointerdown', 'touchstart', 'wheel', 'keydown'].forEach(function (ev) {
    addEventListener(ev, watch, { passive: true, capture: true });
  });
  /* a route change is the moment a stale lock is most likely to be inherited */
  addEventListener('hashchange', function () { setTimeout(checkFrozen, 60); }, { passive: true });

  /* ── 3 · QUIET THE PAGE ─────────────────────────────────────────────────
     The CSS budget in css/v250.css is written by selector, and a selector list
     is always one release behind the markup: the probe after writing it still
     found 90 animating elements on the phone home, because `bcOrbitA` lives on a
     bare `<i>` inside a component whose class nobody predicted. So the last word
     is not CSS at all — it is a walk over what is actually on screen:

       · any element whose computed `animation-iteration-count` is infinite gets
         `animation-name: none`, except the two marquees (pure transform, text
         the shopper reads);
       · any element holding a `will-change` layer promise is released.

     One pass per page, 800 ms after it is on screen (so the entrance motion the
     shopper is meant to see has finished, and the pass cannot fight it), and
     never on a desktop. A phone is then STILL: nothing repaints unless the
     shopper does something, which is what “smooth and lightning fast” means on a
     device with no headroom to spare. */
  var quieted = 0, quietTimer = 0;
  /* v251 — the keep list is the whole tension of “live but cheap”: the marquees
     (transform-only, they carry text) and the three SIGNALS that exist only
     while something is still loading — a pending price, the skeleton, the live
     dot. Everything else that runs forever is decoration and stops. */
  var KEEP = /(^|\s)(rs-ticker-track|rev-track|pr-sk|sk-hero|sk-card|ub-live)(\s|$)/;
  function quietThePage() {
    if (!isMobile() || NOFX) return 0;
    var scope = doc.getElementById('view');
    if (!scope) return 0;
    var nodes = scope.querySelectorAll('*');
    var changed = 0;
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i], st;
      try { st = getComputedStyle(n); } catch (e) { continue; }
      if (!st) continue;
      if (st.willChange && st.willChange !== 'auto') { n.style.willChange = 'auto'; changed++; }
      var it = st.animationIterationCount || '';
      if (it.indexOf('infinite') >= 0 && n.animationName !== 'none') {
        if (!KEEP.test(String(n.className || ''))) { n.style.animationName = 'none'; changed++; }
      } else if (n.animationName !== 'none') {
        /* a child of something that moves forever: its own animation is invisible
           work. Seventy star pops inside the review marquee was the worst case. */
        var host = n.parentElement;
        var depth = 0;
        while (host && depth++ < 6) {
          if (/(^|\s)(rev-track|rs-ticker-track|rev-marquee|ticker-wrap|band-track)(\s|$)/.test(String(host.className || ''))) {
            n.style.animationName = 'none'; changed++; break;
          }
          host = host.parentElement;
        }
      }
    }
    quieted += changed;
    return changed;
  }
  function scheduleQuiet() {
    clearTimeout(quietTimer);
    quietTimer = setTimeout(function () {
      /* requestAnimationFrame first: never measure styles in the same task that
         painted them */
      var raf = window.requestAnimationFrame || function (f) { return setTimeout(f, 16); };
      raf(function () { quietThePage(); });
    }, 800);
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', scheduleQuiet, { once: true });
  else scheduleQuiet();
  addEventListener('hashchange', scheduleQuiet, { passive: true });

  /* ── 4 · measure what the phone is compositing ────────────────────────── */
  function audit() {
    var scope = doc.getElementById('view') || doc.body;
    var nodes = scope.querySelectorAll('*');
    var out = {
      device: isMobile() ? 'phone' : 'desktop',
      elements: nodes.length,
      blurPasses: 0,      /* backdrop-filter — a render surface each */
      blends: 0,          /* mix-blend-mode — an isolated group each */
      filterBlur: 0,      /* filter: blur() — a full-surface blur */
      running: 0,         /* animations actually running */
      infinite: 0,        /* the ones that never stop */
      promoted: 0,        /* will-change promises */
      fixed: 0,
      fpsHint: null,
      frozen: frozenNoted.slice(),
      release: window.__SHIVAA_REL || 0
    };
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i], s;
      try { s = getComputedStyle(n); } catch (e) { continue; }
      if (!s) continue;
      var bf = s.backdropFilter || s.webkitBackdropFilter || '';
      if (bf && bf !== 'none') out.blurPasses++;
      if (s.mixBlendMode && s.mixBlendMode !== 'normal') out.blends++;
      if ((s.filter || '').indexOf('blur') >= 0) out.filterBlur++;
      if (s.animationName && s.animationName !== 'none') {
        out.running++;
        if ((s.animationIterationCount || '').indexOf('infinite') >= 0) out.infinite++;
      }
      if (s.willChange && s.willChange !== 'auto') out.promoted++;
      if (s.position === 'fixed') out.fixed++;
    }
    return out;
  }

  window.Shivaa = window.Shivaa || {};
  window.Shivaa.v250 = {
    get mobile() { return root.classList.contains('shv-mobile'); },
    get nofx() { return NOFX; },
    audit: audit,
    checkFrozen: checkFrozen,
    quiet: quietThePage,
    /** one line, the same shape as the v248/v249 reports */
    report: function () {
      var a = audit();
      return 'still ' + a.release + ' · ' + a.device +
        ' · ' + a.elements + ' els' +
        ' · blur ' + a.blurPasses + ' · blend ' + a.blends + ' · filterBlur ' + a.filterBlur +
        ' · animating ' + a.running + ' (infinite ' + a.infinite + ')' +
        ' · promoted ' + a.promoted +
        ' · quieted ' + quieted +
        ' · frozen-page rescues ' + a.frozen.length +
        (a.frozen.length ? ' [' + a.frozen.join(' ') + ']' : '');
    }
  };
})();

/* ─────────── v251.js ─────────── */
/* ═══════════════════════════════════════════════════════════════════════════
   v251 · “ALIVE” — the two moments that have to feel live, scripted.

   css/v251.css gives the phone its motion back out of the only budget it has
   (transform and opacity, on interaction). Two of the signals cannot be written
   in CSS, because they are answers to an event:

     · THE BAG ANSWERS. Adding something to the bag changes a counter in the
       corner. `.shv-pop` on that badge for 320 ms is the receipt — one element,
       one scale, in the same frame as the tap.

     · THE RATE HAIRLINE. When a fresh gold rate lands (the `rates` event), the
       utility strip sweeps a gold hairline once. It is the only way a shopper
       can tell that a live price actually updated rather than merely being
       there — and it is 520 ms of one pseudo-element.

   Both are added as a class and removed by a timer that cannot leak: the class
   is written on a single element, and the timer is cleared every time the class
   is re-applied, so a burst of changes produces one animation, not a queue.

   AND ONE GUARD: the quiet pass in js/v250.js stops every never-ending animation
   on a phone. The three that are *signals* (a pending price, the skeleton, the
   live dot) must survive it — they exist only while something is still loading,
   so they are named in its keep list. `Shivaa.v251.pulses()` reports how many
   such signals exist right now, which is the number that must stay small.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window.__shvAlive) return;
  window.__shvAlive = true;

  var doc = document;
  var timers = Object.create(null);

  /* ── 1 · the bag answers ──────────────────────────────────────────────── */
  function pop(el) {
    if (!el) return;
    var key = el.id || 'badge';
    clearTimeout(timers[key]);
    el.classList.remove('shv-pop');
    /* a reflow-free restart: removing and re-adding in the same task is enough
       because the class is re-applied after the browser discards the old
       animation — and if it is not, the badge is already at rest. */
    void el.offsetWidth;
    el.classList.add('shv-pop');
    timers[key] = setTimeout(function () { el.classList.remove('shv-pop'); }, 340);
  }

  function watchBadge(id) {
    var el = doc.getElementById(id);
    if (!el || !window.MutationObserver) return;
    var last = el.textContent;
    new MutationObserver(function () {
      var now = el.textContent;
      if (now !== last) { last = now; pop(el); }
    }).observe(el, { childList: true, characterData: true, subtree: true });
  }
  function watchBadges() {
    watchBadge('cartCount');
    watchBadge('wishCount');
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', watchBadges, { once: true });
  else watchBadges();

  /* the decode sweep is a backstop, not the plan: templates emit
     `decoding="async"` themselves (css/../js/app.js thumbAttrs). This catches a
     template that forgot, once, and counts what it caught. */
  window.__shvImgFix = 0;
  function sweep() {
    var fixed = syncImages();
    window.__shvImgFix += fixed.length;
    if (fixed.length && /[?&]v251=1/.test(location.search)) {
      try { console.info('[v251] decoded async late:', fixed.slice(0, 10)); } catch (e) {}
    }
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', function () { setTimeout(sweep, 60); }, { once: true });
  else setTimeout(sweep, 60);
  addEventListener('hashchange', function () { setTimeout(sweep, 700); }, { passive: true });

  /* ── 2 · the rate hairline ────────────────────────────────────────────── */
  var tickT = 0;
  function tick() {
    var el = doc.getElementById('utilRates');
    if (!el) return;
    el.classList.remove('shv-tick');
    void el.offsetWidth;
    el.classList.add('shv-tick');
    clearTimeout(tickT);
    tickT = setTimeout(function () { el.classList.remove('shv-tick'); }, 560);
  }
  addEventListener('rates', tick, { passive: true });

  /* ── 3 · where am I in the page ─────────────────────────────────────────
     One fixed hairline, filled to the shopper's position. Transform only, one
     rAF per scroll frame, and the page height is measured on resize and after a
     route settles rather than read on every frame — reading `scrollHeight` in a
     scroll handler is how a “smooth” feature becomes the jank it answered. */
  var bar = null, docH = 0, winH = 0, rafId = 0, lastP = -1, measT = 0;

  function ensureBar() {
    if (bar && bar.isConnected) return bar;
    if (!doc.body) return null;
    bar = doc.getElementById('shvReadBar');
    if (!bar) {
      bar = doc.createElement('div');
      bar.id = 'shvReadBar';
      bar.setAttribute('aria-hidden', 'true');
      doc.body.appendChild(bar);
    }
    return bar;
  }
  function measure() {
    docH = doc.documentElement.scrollHeight || 0;
    winH = window.innerHeight || doc.documentElement.clientHeight || 0;
  }
  function paint() {
    var b = ensureBar();
    if (!b) return;
    var room = docH - winH;
    var p = room > 24 ? (window.pageYOffset || doc.documentElement.scrollTop || 0) / room : 0;
    if (p < 0) p = 0; if (p > 1) p = 1;
    if (Math.abs(p - lastP) < 0.0015) return;
    lastP = p;
    b.style.transform = 'scaleX(' + p.toFixed(4) + ')';
    b.style.opacity = p > 0.004 ? '.92' : '0';
  }
  function queue() {
    if (rafId) return;
    rafId = requestAnimationFrame(function () { rafId = 0; paint(); });
  }
  function remeasure(later) {
    clearTimeout(measT);
    measT = setTimeout(function () { measure(); lastP = -1; queue(); }, later || 0);
  }
  if (window.requestAnimationFrame) {
    addEventListener('scroll', queue, { passive: true });
    addEventListener('resize', function () { remeasure(60); }, { passive: true });
    addEventListener('orientationchange', function () { remeasure(220); }, { passive: true });
    addEventListener('hashchange', function () { remeasure(420); }, { passive: true });
    addEventListener('load', function () { remeasure(0); }, { once: true });
    if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', function () { remeasure(0); }, { once: true });
    else remeasure(0);
  }

  /* ── 4 · how many signals are running ─────────────────────────────────── */
  function pulses() {
    var scope = doc.getElementById('view') || doc.body;
    var n = 0;
    var pending = scope.querySelectorAll('.pr-sk');
    for (var i = 0; i < pending.length; i++) n++;
    if (doc.querySelector('.ub-live')) n++;
    return n;
  }

  /* ── 5 · every picture decodes off the main thread ──────────────────────
     `decoding="async"` lets the browser decode a JPEG while it is still laying
     out the page instead of blocking the frame the picture lands in. It is the
     cheapest smoothness in the product and the easiest to lose, because every
     new template has to remember it — so this reports the ones that forgot, and
     `?v251=1` prints the list. */
  function syncImages() {
    var bad = [];
    var imgs = doc.images || [];
    for (var i = 0; i < imgs.length; i++) {
      var im = imgs[i];
      if ((im.getAttribute('decoding') || '') !== 'async') {
        im.setAttribute('decoding', 'async');
        bad.push(im.currentSrc || im.src || '(no src)');
      }
    }
    return bad;
  }

  window.Shivaa = window.Shivaa || {};
  window.Shivaa.v251 = {
    pulses: pulses,
    pop: pop,
    tick: tick,
    syncImages: syncImages,
    progress: function () { return lastP < 0 ? 0 : lastP; },
    /** one line, in the same shape as the other three reports */
    report: function () {
      return 'alive ' + (window.__SHIVAA_REL || 0) +
        ' · ' + (doc.documentElement.classList.contains('shv-mobile') ? 'phone' : 'desktop') +
        ' · live pulses ' + pulses() +
        ' · pending prices ' + doc.querySelectorAll('.pr-sk').length +
        ' · sync-decode fixups ' + (window.__shvImgFix || 0) +
        ' · page ' + Math.round((lastP < 0 ? 0 : lastP) * 100) + '%';
    }
  };
})();
